export const MEAL_TYPES = ['breakfast', 'lunch', 'dinner', 'snack']
export const MEAL_SOURCES = ['catalog', 'recent', 'favorite', 'transcript-demo']

export function localDateOf(timestamp) {
  const date = new Date(timestamp)
  const pad = value => (value < 10 ? '0' : '') + value
  return date.getFullYear() + '-' + pad(date.getMonth() + 1) + '-' + pad(date.getDate())
}

export function inferMealType(profile, timestamp) {
  const date = new Date(timestamp)
  const pad = value => (value < 10 ? '0' : '') + value
  const time = pad(date.getHours()) + ':' + pad(date.getMinutes())
  const windows = profile && profile.mealWindows
  if (windows) {
    const order = ['breakfast', 'lunch', 'dinner']
    for (let i = 0; i < order.length; i += 1) {
      const window = windows[order[i]]
      if (window && time >= window.start && time <= window.end) return order[i]
    }
  }
  if (date.getHours() < 10) return 'breakfast'
  if (date.getHours() < 15) return 'lunch'
  if (date.getHours() < 21) return 'dinner'
  return 'snack'
}

export function foodById(foods, foodId) {
  return foods.find(food => food.id === foodId)
}

function stepFor(food) {
  // 确认页统一展示并调整换算后的 g/ml 数量。
  return 50
}

export function itemFromFood(calculateFoodKcal, food, basisAmount) {
  const amount = basisAmount === undefined
    ? food.defaultServing.amount * food.parseUnits[food.defaultServing.unit]
    : basisAmount
  return {
    foodId: food.id,
    name: food.name,
    basisAmount: amount,
    basisUnit: food.basisUnit,
    energyKcalPer100: food.energyKcalPer100,
    kcal: calculateFoodKcal(food, amount),
    step: stepFor(food)
  }
}

export function addFoodToItems(calculateFoodKcal, items, food, basisAmount) {
  const next = items.map(item => Object.assign({}, item))
  const added = itemFromFood(calculateFoodKcal, food, basisAmount)
  const existing = next.find(item => item.foodId === food.id)
  if (existing) {
    existing.basisAmount += added.basisAmount
    existing.kcal = calculateFoodKcal(food, existing.basisAmount)
  } else next.push(added)
  return next
}

export function adjustItem(foods, calculateFoodKcal, items, index, direction) {
  if (!Array.isArray(items) || index < 0 || index >= items.length) return items || []
  const next = items.map(item => Object.assign({}, item))
  const item = next[index]
  const food = foodById(foods, item.foodId)
  if (!food) return items
  const amount = item.basisAmount + (direction < 0 ? -item.step : item.step)
  item.basisAmount = Math.max(item.step, amount)
  item.kcal = calculateFoodKcal(food, item.basisAmount)
  return next
}

export function totalItemsKcal(items) {
  return (items || []).reduce((total, item) => total + item.kcal, 0)
}

export function serializeMealDraft(draft) {
  return JSON.stringify(draft)
}

export function parseMealDraft(draftJson, foods, calculateFoodKcal) {
  try {
    const draft = JSON.parse(draftJson)
    if (!draft || !MEAL_TYPES.includes(draft.mealType) || !MEAL_SOURCES.includes(draft.source) || !Array.isArray(draft.items) || !draft.items.length) return null
    const items = draft.items.map(item => {
      const food = item && foodById(foods, item.foodId)
      if (!food || typeof item.basisAmount !== 'number' || !isFinite(item.basisAmount) || item.basisAmount <= 0) throw new Error('invalid draft item')
      return itemFromFood(calculateFoodKcal, food, item.basisAmount)
    })
    const parsed = { mealType: draft.mealType, source: draft.source, items }
    if (draft.recordId !== undefined) {
      if (typeof draft.recordId !== 'string' || !draft.recordId) return null
      parsed.recordId = draft.recordId
    }
    if (draft.localDate !== undefined) {
      if (typeof draft.localDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(draft.localDate)) return null
      parsed.localDate = draft.localDate
    }
    if (draft.createdAt !== undefined) {
      if (typeof draft.createdAt !== 'number' || !isFinite(draft.createdAt) || draft.createdAt <= 0) return null
      parsed.createdAt = draft.createdAt
    }
    return parsed
  } catch (error) {
    return null
  }
}

export function makeMealRecord(foods, calculateFoodKcal, draft, now) {
  if (!draft || !MEAL_TYPES.includes(draft.mealType) || !MEAL_SOURCES.includes(draft.source) || !draft.items || !draft.items.length) return null
  const timestamp = now || Date.now()
  const items = []
  for (let i = 0; i < draft.items.length; i += 1) {
    const item = draft.items[i]
    const food = item && foodById(foods, item.foodId)
    if (!food || typeof item.basisAmount !== 'number' || !isFinite(item.basisAmount) || item.basisAmount <= 0) return null
    items.push({
      foodId: food.id,
      nameSnapshot: food.name,
      amount: item.basisAmount,
      basisUnit: food.basisUnit,
      energyKcalPer100Snapshot: food.energyKcalPer100,
      kcalSnapshot: calculateFoodKcal(food, item.basisAmount)
    })
  }
  return {
    schemaVersion: 1,
    id: draft.recordId || ('meal-' + timestamp + '-' + Math.floor(Math.random() * 1000000)),
    localDate: draft.localDate || localDateOf(timestamp),
    mealType: draft.mealType,
    source: draft.source,
    items,
    totalKcalSnapshot: items.reduce((sum, item) => sum + item.kcalSnapshot, 0),
    createdAt: draft.createdAt || timestamp,
    updatedAt: timestamp
  }
}

export function upsertMeal(meals, record) {
  const next = (meals || []).slice()
  const index = next.findIndex(item => item.id === record.id)
  if (index >= 0) next[index] = record
  else next.push(record)
  return next
}

export function deleteMeal(meals, id) {
  return (meals || []).filter(meal => meal.id !== id)
}

export function todaySummary(meals, localDate) {
  const records = (meals || []).filter(meal => meal.localDate === localDate)
  const status = { breakfast: 'pending', lunch: 'pending', dinner: 'pending' }
  records.forEach(meal => { if (status[meal.mealType]) status[meal.mealType] = 'completed' })
  return { records, totalKcal: records.reduce((sum, meal) => sum + meal.totalKcalSnapshot, 0), status }
}

export function syncMealPromptState(promptState, meals, localDate) {
  const summary = todaySummary(meals, localDate)
  const previous = promptState && promptState.localDate === localDate ? promptState : {}
  const next = { localDate }
  ;['breakfast', 'lunch', 'dinner'].forEach(type => {
    if (summary.status[type] === 'completed') next[type] = { status: 'completed' }
    else if (previous[type] && previous[type].status !== 'completed') next[type] = Object.assign({}, previous[type])
    else next[type] = { status: 'pending' }
  })
  return next
}

export function activeMealType(profile, timestamp) {
  const windows = profile && profile.mealWindows
  if (!windows) return null
  const date = new Date(timestamp)
  const pad = value => (value < 10 ? '0' : '') + value
  const time = pad(date.getHours()) + ':' + pad(date.getMinutes())
  const order = ['breakfast', 'lunch', 'dinner']
  for (let i = 0; i < order.length; i += 1) {
    const window = windows[order[i]]
    if (window && time >= window.start && time <= window.end) return order[i]
  }
  return null
}

export function mealCapsuleView(profile, meals, promptState, timestamp) {
  const mealType = activeMealType(profile, timestamp)
  if (!mealType) return { visibility: 'hidden', mealType: null }
  const localDate = localDateOf(timestamp)
  const synced = syncMealPromptState(promptState, meals, localDate)
  const records = (meals || []).filter(meal => meal.localDate === localDate && meal.mealType === mealType)
  if (records.length) {
    return {
      visibility: 'collapsed', status: 'completed', mealType,
      kcal: records.reduce((sum, meal) => sum + meal.totalKcalSnapshot, 0)
    }
  }
  const entry = synced[mealType]
  if (entry.status === 'later' && entry.remindAt > timestamp) return { visibility: 'collapsed', status: 'later', mealType, remindAt: entry.remindAt }
  if (entry.status === 'skipped') return { visibility: 'collapsed', status: 'skipped', mealType }
  return { visibility: 'expanded', status: 'pending', mealType, actions: ['record', 'later', 'skip'] }
}

function updateActivePrompt(profile, meals, promptState, timestamp, entry) {
  const mealType = activeMealType(profile, timestamp)
  if (!mealType) return { changed: false, mealType: null, promptState }
  const localDate = localDateOf(timestamp)
  const synced = syncMealPromptState(promptState, meals, localDate)
  if (synced[mealType].status === 'completed') return { changed: false, mealType, promptState: synced }
  const next = Object.assign({}, synced)
  next[mealType] = entry
  return { changed: true, mealType, promptState: next }
}

export function setActiveMealLater(profile, meals, promptState, timestamp) {
  return updateActivePrompt(profile, meals, promptState, timestamp, { status: 'later', remindAt: timestamp + 15 * 60 * 1000 })
}

export function skipActiveMeal(profile, meals, promptState, timestamp) {
  return updateActivePrompt(profile, meals, promptState, timestamp, { status: 'skipped' })
}

export function updateRecent(recentFoodIds, items) {
  const ids = (items || []).map(item => item.foodId).reverse()
  return ids.concat(recentFoodIds || []).filter((id, index, all) => all.indexOf(id) === index).slice(0, 12)
}

export function addFavorite(favorites, record, now) {
  const first = record.items[0]
  const names = { breakfast: '早餐', lunch: '午餐', dinner: '晚餐', snack: '加餐' }
  const favorite = {
    id: 'favorite-' + record.id,
    name: names[record.mealType] + ' · ' + first.nameSnapshot,
    createdAt: now || record.updatedAt,
    updatedAt: now || record.updatedAt,
    items: record.items.map(item => ({ foodId: item.foodId, amount: item.amount, basisUnit: item.basisUnit }))
  }
  return [favorite].concat((favorites || []).filter(item => item.id !== favorite.id)).slice(0, 8)
}

export function draftFromRecord(foods, calculateFoodKcal, record) {
  return {
    recordId: record.id, createdAt: record.createdAt, localDate: record.localDate,
    mealType: record.mealType, source: record.source,
    items: record.items.map(item => itemFromFood(calculateFoodKcal, foodById(foods, item.foodId), item.amount))
  }
}
export const EXERCISE_ACTIVITIES = [
  { id: 'brisk_walk', name: '快走', met: 3.5 },
  { id: 'run', name: '跑步', met: 8.0 },
  { id: 'cycle', name: '骑行', met: 6.8 },
  { id: 'rope', name: '跳绳', met: 10.0 },
  { id: 'strength', name: '力量训练', met: 5.0 },
  { id: 'yoga', name: '瑜伽', met: 2.5 }
]

function finiteNumber(value) {
  return typeof value === 'number' && isFinite(value)
}

function pad(value) {
  return value < 10 ? '0' + value : String(value)
}

export function localDateOf(timestamp) {
  const date = new Date(timestamp)
  return date.getFullYear() + '-' + pad(date.getMonth() + 1) + '-' + pad(date.getDate())
}

function parseLocalDate(localDate) {
  if (typeof localDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(localDate)) return null
  const parts = localDate.split('-').map(Number)
  const date = new Date(parts[0], parts[1] - 1, parts[2])
  if (date.getFullYear() !== parts[0] || date.getMonth() !== parts[1] - 1 || date.getDate() !== parts[2]) return null
  return date
}

function shiftLocalDate(localDate, days) {
  const date = parseLocalDate(localDate)
  if (!date) return null
  date.setDate(date.getDate() + days)
  return localDateOf(date.getTime())
}

export function activityById(activity) {
  return EXERCISE_ACTIVITIES.find(item => item.id === activity) || null
}

export function calculateExerciseKcal(met, weightKg, durationMinutes) {
  if (!finiteNumber(met) || met <= 0) throw new RangeError('MET 必须是正的有限数')
  if (!finiteNumber(weightKg) || weightKg < 25 || weightKg > 250) throw new RangeError('体重必须在 25–250 kg')
  if (!Number.isInteger(durationMinutes) || durationMinutes < 1 || durationMinutes > 600) throw new RangeError('时长必须是 1–600 分钟的整数')
  return Math.round(met * 3.5 * weightKg / 200 * durationMinutes)
}

export function createExerciseRecord(activity, weightKg, durationMinutes, now) {
  const definition = activityById(activity)
  const timestamp = now === undefined ? Date.now() : now
  if (!definition || !finiteNumber(timestamp) || timestamp <= 0) return null
  try {
    return {
      schemaVersion: 1,
      id: 'exercise-' + timestamp + '-' + Math.floor(Math.random() * 1000000),
      localDate: localDateOf(timestamp),
      activity: definition.id,
      metSnapshot: definition.met,
      weightKgSnapshot: weightKg,
      durationMinutes,
      kcalSnapshot: calculateExerciseKcal(definition.met, weightKg, durationMinutes),
      createdAt: timestamp,
      updatedAt: timestamp
    }
  } catch (error) {
    return null
  }
}

export function editExerciseRecord(record, activity, weightKg, durationMinutes, now) {
  if (!record || typeof record.id !== 'string' || !record.id || !parseLocalDate(record.localDate) || !finiteNumber(record.createdAt) || record.createdAt <= 0) return null
  const definition = activityById(activity)
  const timestamp = now === undefined ? Date.now() : now
  if (!definition || !finiteNumber(timestamp) || timestamp < record.createdAt) return null
  try {
    return {
      schemaVersion: 1,
      id: record.id,
      localDate: record.localDate,
      activity: definition.id,
      metSnapshot: definition.met,
      weightKgSnapshot: weightKg,
      durationMinutes,
      kcalSnapshot: calculateExerciseKcal(definition.met, weightKg, durationMinutes),
      createdAt: record.createdAt,
      updatedAt: timestamp
    }
  } catch (error) {
    return null
  }
}

export function upsertExercise(exercises, record) {
  const next = (exercises || []).slice()
  const index = next.findIndex(item => item.id === record.id)
  if (index >= 0) next[index] = record
  else next.push(record)
  return next
}

export function deleteExercise(exercises, id) {
  return (exercises || []).filter(record => record.id !== id)
}

export function dailyEnergySummary(meals, exercises, localDate, dailyTargetKcal) {
  const intakeKcal = (meals || []).filter(item => item.localDate === localDate).reduce((sum, item) => sum + item.totalKcalSnapshot, 0)
  const exerciseKcal = (exercises || []).filter(item => item.localDate === localDate).reduce((sum, item) => sum + item.kcalSnapshot, 0)
  const netKcal = intakeKcal - exerciseKcal
  return { intakeKcal, exerciseKcal, netKcal, remainingKcal: dailyTargetKcal - netKcal }
}

export function sevenDayEnergyTrend(meals, exercises, todayLocalDate, dailyTargetKcal) {
  if (!parseLocalDate(todayLocalDate)) return []
  const result = []
  for (let offset = -6; offset <= 0; offset += 1) {
    const localDate = shiftLocalDate(todayLocalDate, offset)
    result.push(Object.assign({ localDate }, dailyEnergySummary(meals, exercises, localDate, dailyTargetKcal)))
  }
  return result
}

function pendingPromptState(localDate) {
  return {
    localDate,
    breakfast: { status: 'pending' },
    lunch: { status: 'pending' },
    dinner: { status: 'pending' }
  }
}

export function retainRecentLocalDays(state, now) {
  const timestamp = finiteNumber(now) && now > 0 ? now : Date.now()
  const today = localDateOf(timestamp)
  const cutoff = shiftLocalDate(today, -29)
  const keep = record => record.localDate > today || record.localDate >= cutoff
  const meals = (state.meals || []).filter(keep)
  const exercises = (state.exercises || []).filter(keep)
  const resetPrompt = !state.mealPromptState || state.mealPromptState.localDate !== today
  const changed = meals.length !== (state.meals || []).length || exercises.length !== (state.exercises || []).length || resetPrompt
  if (!changed) return { changed: false, state }
  return {
    changed: true,
    state: Object.assign({}, state, {
      meals,
      exercises,
      mealPromptState: resetPrompt ? pendingPromptState(today) : state.mealPromptState,
      lastMaintenanceAt: timestamp
    })
  }
}
import storage from '@system.storage'

export const STORAGE_KEY = 'shihe_state_v1'

export function loadState(validateState, done) {
  let completed = false
  const finish = result => {
    if (completed) return
    completed = true
    done(result)
  }
  try {
    storage.get({
      key: STORAGE_KEY,
      success(value) {
        if (value === undefined || value === null || value === '') {
          finish({ status: 'empty' })
          return
        }
        try {
          const state = typeof value === 'string' ? JSON.parse(value) : value
          finish(validateState(state) ? { status: 'ok', state } : { status: 'corrupt' })
        } catch (error) {
          finish({ status: 'corrupt' })
        }
      },
      fail() {
        finish({ status: 'unavailable' })
      }
    })
  } catch (error) {
    finish({ status: 'unavailable' })
  }
}

export function saveState(validateState, state, done) {
  let completed = false
  const finish = result => {
    if (completed) return
    completed = true
    done(result)
  }
  if (!validateState(state)) {
    finish({ status: 'invalid' })
    return
  }
  let serialized
  try {
    serialized = JSON.stringify(state)
  } catch (error) {
    finish({ status: 'invalid' })
    return
  }
  try {
    storage.set({
      key: STORAGE_KEY,
      value: serialized,
      success() {
        loadState(validateState, result => {
          if (result.status === 'ok' && JSON.stringify(result.state) === serialized) finish({ status: 'ok' })
          else finish({ status: 'verify-failed' })
        })
      },
      fail() {
        finish({ status: 'unavailable' })
      }
    })
  } catch (error) {
    finish({ status: 'unavailable' })
  }
}
export const STATE_SCHEMA_VERSION = 1

export function defaultMealWindows() {
  return {
    breakfast: { start: '07:00', end: '09:30' },
    lunch: { start: '11:30', end: '14:00' },
    dinner: { start: '17:30', end: '20:30' }
  }
}

export function emptyState() {
  return {
    schemaVersion: STATE_SCHEMA_VERSION,
    profile: null,
    meals: [],
    exercises: [],
    recentFoodIds: [],
    favoriteMeals: [],
    mealPromptState: {
      localDate: '',
      breakfast: { status: 'pending' },
      lunch: { status: 'pending' },
      dinner: { status: 'pending' }
    },
    lastMaintenanceAt: 0
  }
}

function finiteNumber(value) {
  return typeof value === 'number' && isFinite(value)
}

function validTime(value) {
  return typeof value === 'string' && /^([01]\d|2[0-3]):[0-5]\d$/.test(value)
}

function validWindow(window) {
  return window && validTime(window.start) && validTime(window.end) && window.start < window.end
}

function validPromptEntry(entry) {
  if (!entry || typeof entry !== 'object' || !['pending', 'later', 'skipped', 'completed'].includes(entry.status)) return false
  const hasRemindAt = Object.prototype.hasOwnProperty.call(entry, 'remindAt')
  if (entry.status === 'later' && !hasRemindAt) return false
  return !hasRemindAt || (finiteNumber(entry.remindAt) && entry.remindAt > 0)
}

const MEAL_TYPES = ['breakfast', 'lunch', 'dinner', 'snack']
const MEAL_SOURCES = ['catalog', 'recent', 'favorite', 'transcript-demo']
const EXERCISE_METS = { brisk_walk: 3.5, run: 8.0, cycle: 6.8, rope: 10.0, strength: 5.0, yoga: 2.5 }
function validDate(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(value)) return false
  const parts = value.split('-').map(Number)
  const date = new Date(parts[0], parts[1] - 1, parts[2])
  return date.getFullYear() === parts[0] && date.getMonth() === parts[1] - 1 && date.getDate() === parts[2]
}
function validId(value) { return typeof value === 'string' && value.length > 0 && value.length <= 120 }
function validMealItem(item, foodIds) {
  if (!item || !foodIds.includes(item.foodId) || typeof item.nameSnapshot !== 'string' || !item.nameSnapshot) return false
  if (!finiteNumber(item.amount) || item.amount <= 0 || !['g', 'ml'].includes(item.basisUnit)) return false
  if (!finiteNumber(item.energyKcalPer100Snapshot) || item.energyKcalPer100Snapshot < 0) return false
  return Number.isInteger(item.kcalSnapshot) && item.kcalSnapshot === Math.round(item.energyKcalPer100Snapshot * item.amount / 100)
}
function validMeal(meal, foodIds) {
  if (!meal || meal.schemaVersion !== 1 || !validId(meal.id) || !validDate(meal.localDate)) return false
  if (!MEAL_TYPES.includes(meal.mealType) || !MEAL_SOURCES.includes(meal.source)) return false
  if (!finiteNumber(meal.createdAt) || meal.createdAt <= 0 || !finiteNumber(meal.updatedAt) || meal.updatedAt < meal.createdAt) return false
  if (!Array.isArray(meal.items) || !meal.items.length || !meal.items.every(item => validMealItem(item, foodIds))) return false
  return Number.isInteger(meal.totalKcalSnapshot) && meal.totalKcalSnapshot === meal.items.reduce((sum, item) => sum + item.kcalSnapshot, 0)
}
function validFavorite(favorite, foodIds) {
  if (!favorite || !validId(favorite.id) || typeof favorite.name !== 'string' || !favorite.name) return false
  if (!finiteNumber(favorite.createdAt) || favorite.createdAt <= 0 || !finiteNumber(favorite.updatedAt) || favorite.updatedAt < favorite.createdAt) return false
  return Array.isArray(favorite.items) && favorite.items.length > 0 && favorite.items.every(item => item && foodIds.includes(item.foodId) && finiteNumber(item.amount) && item.amount > 0 && ['g', 'ml'].includes(item.basisUnit))
}
function validExercise(record) {
  if (!record || record.schemaVersion !== 1 || !validId(record.id) || !validDate(record.localDate)) return false
  if (!Object.prototype.hasOwnProperty.call(EXERCISE_METS, record.activity)) return false
  if (!finiteNumber(record.metSnapshot) || record.metSnapshot <= 0 || record.metSnapshot > 30) return false
  if (!finiteNumber(record.weightKgSnapshot) || record.weightKgSnapshot < 25 || record.weightKgSnapshot > 250) return false
  if (!Number.isInteger(record.durationMinutes) || record.durationMinutes < 1 || record.durationMinutes > 600) return false
  if (!finiteNumber(record.createdAt) || record.createdAt <= 0 || !finiteNumber(record.updatedAt) || record.updatedAt < record.createdAt) return false
  const expectedKcal = Math.round(record.metSnapshot * 3.5 * record.weightKgSnapshot / 200 * record.durationMinutes)
  return Number.isInteger(record.kcalSnapshot) && record.kcalSnapshot === expectedKcal
}

export function normalizeProfile(profile) {
  if (!profile || profile.schemaVersion !== STATE_SCHEMA_VERSION) return null
  if (!finiteNumber(profile.weightKg) || profile.weightKg < 25 || profile.weightKg > 250) return null
  if (!Number.isInteger(profile.dailyTargetKcal) || profile.dailyTargetKcal < 800 || profile.dailyTargetKcal > 5000) return null
  const windows = profile.mealWindows
  if (!windows || !validWindow(windows.breakfast) || !validWindow(windows.lunch) || !validWindow(windows.dinner)) return null
  if (!finiteNumber(profile.disclaimerAcceptedAt) || profile.disclaimerAcceptedAt <= 0) return null
  if (!finiteNumber(profile.updatedAt) || profile.updatedAt <= 0) return null
  return {
    schemaVersion: STATE_SCHEMA_VERSION,
    weightKg: Math.round(profile.weightKg * 10) / 10,
    dailyTargetKcal: profile.dailyTargetKcal,
    mealWindows: {
      breakfast: { start: windows.breakfast.start, end: windows.breakfast.end },
      lunch: { start: windows.lunch.start, end: windows.lunch.end },
      dinner: { start: windows.dinner.start, end: windows.dinner.end }
    },
    disclaimerAcceptedAt: profile.disclaimerAcceptedAt,
    updatedAt: profile.updatedAt
  }
}

export function validateProfile(profile) {
  return normalizeProfile(profile) !== null
}

export function validateState(state, foods) {
  if (!Array.isArray(foods)) return false
  const foodIds = foods.map(item => item.id)
  if (!state || state.schemaVersion !== STATE_SCHEMA_VERSION) return false
  if (state.profile !== null && !validateProfile(state.profile)) return false
  if (!Array.isArray(state.meals) || !Array.isArray(state.exercises) || !Array.isArray(state.recentFoodIds) || !Array.isArray(state.favoriteMeals)) return false
  if (!state.meals.every(meal => validMeal(meal, foodIds)) || state.meals.some((meal, index) => state.meals.findIndex(other => other.id === meal.id) !== index)) return false
